{
  "id": "atlas.plugin.example",
  "name": "ATLAS Example Plugin",
  "nameI18n": {
    "de": "ATLAS-Beispiel-Plugin",
    "en": "ATLAS Example Plugin"
  },
  "version": "0.1.0",
  "description": "A minimal working ATLAS plugin template.",
  "descriptionI18n": {
    "de": "Eine minimale, funktionsfähige Vorlage für ATLAS-Plugins.",
    "en": "A minimal working template for ATLAS plugins."
  },
  "status": "active",
  "order": 100,
  "entry": "/plugin-assets/atlas-plugin/index.html",
  "icon": "icon.svg",
  "logo": "logo.svg",
  "preview": "preview.svg",
  "capabilities": [
    "atlas.plugin.example"
  ]
}

:root {
  color-scheme: dark;
  font: 16px/1.5 system-ui, sans-serif;
  color: #e8eef5;
  background: #101820;
}

* { box-sizing: border-box; }

body {
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px;
}

.plugin-card {
  width: min(100%, 560px);
  padding: 28px;
  border: 1px solid #334554;
  border-radius: 18px;
  background: #192631;
  box-shadow: 0 20px 60px #0005;
}

.plugin-icon { width: 56px; height: 56px; }
.eyebrow { margin: 20px 0 4px; color: #58d3bd; font-size: 12px; font-weight: 700; letter-spacing: .08em; }
h1 { margin: 0; font-size: clamp(1.7rem, 5vw, 2.4rem); }
.description { color: #b6c4ce; }
button { padding: 10px 16px; border: 0; border-radius: 9px; background: #168f83; color: white; font: inherit; font-weight: 700; cursor: pointer; }
button:hover { background: #20a99b; }
.result { min-height: 1.5em; color: #58d3bd; }

const button = document.querySelector("#example-button");
const result = document.querySelector("#result");

button.addEventListener("click", () => {
  result.textContent = "The plugin page is running.";
});
